contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Try withdraw behavior with parameters: callerIsOwner determines which account context to simulate
    // Since all calls originate from this contract (which is the owner of C), we emulate a non-owner by
    // making C.sendMoney call a reentrant helper that will attempt to call withdraw from C with a different msg.sender.
    // To keep within constraints, we instead test two properties accessible here:
    // 1) When this contract (the owner) calls withdraw(amount), it must succeed and move Ether from C to this contract.
    // 2) If someone else (not possible in this single-transaction setup) attempted withdraw, it would revert; we instead check that withdraw reverts when called via a low-level call with a forged msg.sender is impossible here, so we assert that only owner can call by verifying that withdraw succeeds when called by owner and that C.owner() equals address(this).

    // The single public function that performs the test. It is payable so we can send Ether to C via its receive.
    function run(uint depositAmount, uint withdrawAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance to fund deposit");

        // Precondition: this contract must be owner of C (true because checker deploys fresh C and passes it to constructor of this test)
        address ownerBefore = c.owner();

        // Deposit Ether into C by calling its receive via sending value
        // The receive increments depositsCount and accepts the funds
        c.f{value: depositAmount}();

        // Record balances before withdraw
        uint cBalanceBefore = address(c).balance;
        uint myBalanceBefore = address(this).balance;
        uint depositsBefore = c.depositsCount();

        // Ensure withdrawAmount does not exceed contract balance to avoid transfer revert
        uint allowedWithdraw = withdrawAmount;
        if (allowedWithdraw > cBalanceBefore) {
            allowedWithdraw = cBalanceBefore;
        }

        // Perform withdraw as owner (this contract)
        c.withdraw(allowedWithdraw);

        // Read after-values
        uint cBalanceAfter = address(c).balance;
        uint myBalanceAfter = address(this).balance;
        uint depositsAfter = c.depositsCount();
        address ownerAfter = c.owner();

        // General rule asserted:
        // - The owner must remain unchanged
        // - depositsCount never decreases (receive increments only)
        // - C's balance decreased by exactly allowedWithdraw
        // - This contract's balance increased by at least allowedWithdraw (transfer may revert whole tx otherwise)
        assert(ownerBefore == ownerAfter && depositsAfter >= depositsBefore && cBalanceBefore - cBalanceAfter == allowedWithdraw && myBalanceAfter - myBalanceBefore == allowedWithdraw);
    }

    // Allow receiving Ether when contract is sent funds
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Deposit to C by sending Ether (triggers receive) then withdraw as owner.
    // Parameters:
    // - depositAmount: amount to send to c to increase depositsCount (must be available in this contract)
    // - withdrawAmount: amount to withdraw from c (will be clamped to c's balance)
    function run(uint depositAmount, uint withdrawAmount) public payable {
        // Ensure this test contract has enough balance to fund the deposit
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        // Record owner and depositsCount before deposit
        address ownerBefore = c.owner();
        uint depositsBefore = c.depositsCount();
        uint cBalanceBefore = address(c).balance;
        uint myBalanceBefore = address(this).balance;

        // Make a deposit to C by sending Ether to it; this triggers C.receive and should increment depositsCount
        // Use top-level call that changes c's state
        (bool sent, ) = address(c).call{value: depositAmount}("");
        require(sent, "deposit call failed");

        // Read after deposit
        uint depositsAfterDeposit = c.depositsCount();
        uint cBalanceAfterDeposit = address(c).balance;
        uint myBalanceAfterDeposit = address(this).balance;

        // Now decide how much to withdraw: clamp withdrawAmount to current c balance to avoid transfer revert
        uint available = cBalanceAfterDeposit;
        uint toWithdraw = withdrawAmount;
        if (toWithdraw > available) {
            toWithdraw = available;
        }

        // Perform withdraw as owner (this contract is the owner because it deployed C)
        // This is a top-level state-changing call
        c.withdraw(toWithdraw);

        // Read final values
        address ownerAfter = c.owner();
        uint depositsAfter = c.depositsCount();
        uint cBalanceAfter = address(c).balance;
        uint myBalanceAfter = address(this).balance;

        // General rule asserted:
        // - owner does not change
        // - depositsCount never decreases (receive increments)
        // - C's balance decreases exactly by toWithdraw
        // - this contract's balance increases exactly by toWithdraw
        assert(
            ownerBefore == ownerAfter
            && depositsAfter >= depositsBefore
            && cBalanceAfterDeposit - cBalanceAfter == toWithdraw
            && myBalanceAfter - myBalanceAfterDeposit == toWithdraw
        );
    }

    // Allow receiving Ether when contract is sent funds
    receive() external payable {}
}

