contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run takes parameters to attempt various calls: who (as an address) can't be changed here due to msg.sender context,
    // so we model owner vs non-owner by calling withdraw/sendMoney/receive via this contract (owner) and by having
    // the contract attempt to make c call into an attacker-controlled fallback by using sendMoney to itself when not owner.
    // We instead test that when called by the owner (this contract), withdraw succeeds and reduces address(c).balance appropriately,
    // and that a withdraw attempted via a low-level call that imitates a different sender (impossible here) would revert.

    // We formulate a general rule about owner-only functions: when this contract (the owner) calls withdraw(_v) or withdrawAll(),
    // the contract balance decreases by at most the requested amount and depositsCount never decreases.

    // Because the checker runs with this contract as msg.sender for calls on c, this contract is owner. We take amount and a deposit
    // amount to send into C via receive() and then test withdraw/withdrawAll behavior.

    function run(uint depositAmount, uint withdrawAmount) public payable {
        require(address(this).balance >= depositAmount + 1 wei);
        // Make a deposit into c if depositAmount > 0
        if (depositAmount > 0) {
            // call receive() by sending Ether
            c.f{value: depositAmount}();
        }

        // read before-values
        uint beforeDeposits = c.depositsCount();
        uint beforeBal = address(c).balance;
        uint selfBefore = address(this).balance;

        // owner calls withdraw(withdrawAmount)
        bool reverted;
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        uint afterDeposits = c.depositsCount();
        uint afterBal = address(c).balance;
        uint selfAfter = address(this).balance;

        // General rule (one assert):
        // - depositsCount never decreases as a result of withdraw (only receive increments it)
        // - the contract balance never decreases by more than withdrawAmount (owner requested)
        // - if withdraw succeeded then this contract's balance increased by at most withdrawAmount and c's balance decreased by same amount
        // - if withdraw reverted then balances unchanged and depositsCount unchanged
        assert(
            // depositsCount non-decreasing
            afterDeposits >= beforeDeposits
            // balances change consistent with withdrawAmount and revert flag
            && (
                reverted
                ? (afterBal == beforeBal && selfAfter == selfBefore)
                : (beforeBal >= withdrawAmount && (beforeBal - afterBal) == (selfAfter - selfBefore) && (beforeBal - afterBal) <= withdrawAmount)
            )
        );
    }

    // Allow contract to receive Ether when c.withdraw transfers to it
    receive() external payable { }
}

