        if (depositAmount > 0) {
            // call receive by sending value to c
            // must ensure this contract has the Ether (checked above)
            (bool sent, ) = address(c).call{value: depositAmount}("\x00");
            // the low-level call to trigger receive might return true; if it reverts the whole run would revert
            require(sent, "deposit failed");
        }

        // read before-values
        uint beforeDeposits = c.depositsCount();
        uint beforeBal = address(c).balance;
        uint selfBefore = address(this).balance;

        // Owner (this contract) calls withdraw(withdrawAmount)
        bool reverted;
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
