        uint afterBal = address(c).balance;
        uint selfAfter = address(this).balance;

        // General invariant asserted for all inputs:
        // - depositsCount never decreases
        // - if withdraw reverted: balances and depositsCount unchanged
        // - if withdraw succeeded: c's balance decreased by delta, this contract's balance increased by same delta,
        //   and that delta is <= withdrawAmount
        assert(
            afterDeposits >= beforeDeposits
            && (
                reverted
                ? (afterDeposits == beforeDeposits && afterBal == beforeBal && selfAfter == selfBefore)
                : (
                    // withdrawal succeeded: balances moved consistently
                    beforeBal >= afterBal
                    && selfAfter >= selfBefore
                    && (beforeBal - afterBal) == (selfAfter - selfBefore)
                    && (beforeBal - afterBal) <= withdrawAmount
                )
            )
        );
    }

    // accept Ether transfers from c.withdraw
    receive() external payable { }
