contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept parameters: callerIsOwner indicates whether this test should act as owner or not;
    // amount is Ether to send into contract before withdraw attempt; withdrawAmount is the value to attempt to withdraw.
    // To simulate non-owner calls, we'll use sendMoney as owner to transfer funds out to this contract if needed,
    // but calls to withdraw must be performed by this contract (which is NOT the original owner of c unless the checker deployed c pointing owner to this contract).
    function run(bool callerIsOwner, uint amount, uint withdrawAmount) public payable {
        require(true);
        // Ensure we have funds to send to c if needed
        if (amount > 0) {
            // Our test contract must have balance to send; require that the transaction provided enough funds.
            require(address(this).balance >= amount);
            // Send Ether to c using its receive() by a plain call (transfer of value to c address)
            (bool sent, ) = address(c).call{value: amount}("");
            // sent may be false if receive reverts (shouldn't for valid amounts), but we proceed regardless.
        }

        // Record balance before withdraw
        uint balBefore = address(c).balance;

        bool didRevert = false;
        // We need to attempt withdraw as either owner or non-owner. The checker deploys C fresh; owner is msg.sender at C creation.
        // Our contract is the one interacting now; if callerIsOwner==true we assert that this contract is the owner by trying a privileged call first.
        // Try to detect owner status by calling a function that only owner can call and observing revert.
        // We'll attempt withdraw with 0 first to probe ownership without changing balances.
        try c.withdraw(uint(0)) {
            // no revert -> this contract is owner
            if (!callerIsOwner) {
                // The test wanted caller to be non-owner, but the contract is owner; to satisfy the hook we flip nothing and proceed.
            }
        } catch {
            // revert when calling withdraw(0) indicates this contract is not owner
        }

        // Now attempt the actual withdraw and capture revert
        try c.withdraw(withdrawAmount) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        uint balAfter = address(c).balance;

        // General rule: if the withdraw call reverted then the contract balance must be unchanged;
        // if it did not revert then balance must have decreased by exactly withdrawAmount (or to zero if withdrawAmount > balBefore transfers whole balance),
        // but since withdraw uses transfer which throws on failure and only owner can call, successful withdraw must reduce balance by min(withdrawAmount, balBefore).
        uint expectedDecrease = withdrawAmount;
        if (withdrawAmount > balBefore) {
            expectedDecrease = balBefore;
        }

        assert(didRevert ? (balAfter == balBefore) : (balBefore >= balAfter && (balBefore - balAfter) == expectedDecrease));
    }

    // allow receiving Ether when c.sendMoney calls back
    receive() external payable {}
}

