    constructor(C _c) { c = _c; }

    // single public test: caller will be this contract (which deployed C), so it's the owner
    // param fundAmount: amount of Ether to send into c before testing (to allow withdraw to transfer out)
    function run(uint fundAmount) public payable {
        require(address(this).balance >= fundAmount);

        // Fund contract c by sending plain Ether to trigger receive()
        if (fundAmount > 0) {
            (bool ok, ) = address(c).call{value: fundAmount}("");
            // ignore whether it reverted; if it reverted, balance won't have increased
            ok; // silence compiler warning
        }

        // observe balance before
        uint balBefore = address(c).balance;

