    // transfer at most the requested amount and do not increase C.balance; and that when a
    // non-owner would call them they must revert (we simulate by deploying calls from this
    // contract only — but we can observe that owner is this contract by reading c.owner()).

    function run(uint sendAmount, uint withdrawAmount, address payable target, bytes calldata data) public payable {
        // Allow sending Ether to c via the receive() of C by calling c with value
        // Ensure we have enough balance to fund the deposit we will send
        require(address(this).balance >= sendAmount, "insufficient balance to fund sendAmount");

        // Read owner and initial balances
        address ownerBefore = c.owner();
        uint balBefore = address(c).balance;

        // Deposit Ether into C by invoking receive() (this increments depositsCount)
        // This is a top-level state-changing call as required
        c.sendMoney{value: 0}(address(0), 0, ""); // harmless call: owner-only but we are owner so non-reverting

        // If this contract is not the owner, then owner-only calls should revert when invoked.
        // Determine whether this contract is owner of c
        bool iAmOwner = (ownerBefore == address(this));

        bool withdrawReverted;
        // Try withdraw: must succeed if and only if this contract is owner
        try c.withdraw(withdrawAmount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Record balance after withdraw attempt
        uint balAfterWithdraw = address(c).balance;

        bool sendReverted;
