        try c.sendMoney(target, withdrawAmount, data) {
            sendReverted = false;
        } catch {
            sendReverted = true;
        }

        uint balAfterSend = address(c).balance;

        // General rule asserted:
        // - If this contract is owner, ownerBefore==address(this), then withdraw and sendMoney must NOT increase c.balance (they may decrease it at most by the requested amounts), so balAfterWithdraw <= balBefore and balAfterSend <= balAfterWithdraw.
        // - If this contract is NOT owner, both calls must have reverted and balance must be unchanged.
        assert(
            iAmOwner
            ? ( // owner case
                withdrawReverted == false && sendReverted == false &&
                balAfterWithdraw <= balBefore && balAfterSend <= balAfterWithdraw
              )
            : ( // non-owner case
                withdrawReverted == true && sendReverted == true && balAfterWithdraw == balBefore && balAfterSend == balBefore
              )
        );
    }

