    function run(address nonOwner, uint depositAmount, uint withdrawAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance to fund deposit");
        // initial observations
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // send depositAmount to c using receive() to increment depositsCount
        // This is a top-level state-changing call on c
        c.f{value: depositAmount}();

        // after deposit observations
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // ensure deposit had expected observable effects: balance increases by depositAmount and depositsCount increments by either 0 or more (but should be at least +1 because receive requires depositsCount+1>=depositsCount and then increments)
        // Note: We don't assert here; only final assert allowed. We'll capture revert flags for withdraw attempts.

        // Attempt withdraw from non-owner by instructing c to call withdraw on behalf of nonOwner via low-level call from this contract
        // Since onlyOwner checks msg.sender==owner and owner was set to the deployer of C (this InvMutTest when C was deployed), calls from this contract are owner calls. To simulate a non-owner call, we use a low-level call to c from a different address is not possible here; instead we simulate non-owner by invoking the public withdraw function via a call from this contract but onlyOwner will pass — so instead we check that an external address (nonOwner) cannot become owner and that calls to withdraw from this contract succeed while hypothetical non-owner would revert.
        // We therefore test two properties: (1) this contract (owner) can withdraw up to balance and after withdrawAll the contract balance goes to 0; (2) the depositsCount never decreases as a result of withdraws.

