        assert(
            (!withdrewReverted && beforeDeposits <= finalDeposits && afterDeposits <= finalDeposits && finalBalance + cap == afterBalance)
            || (withdrewReverted && finalBalance == afterBalance && finalDeposits == afterDeposits)
        );
    }

