contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // sendAmount is the Ether amount to forward to c via its receive().
    function run(uint sendAmount) public payable {
        require(address(this).balance >= sendAmount);

        // observe before-values
        uint beforeCount = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Perform a direct call to C to trigger its receive() (must be a top-level call)
        // We call the contract directly so that its receive() is invoked when msg.data is empty.
        // Use try/catch on the external call to capture revert without nesting the state-changing call.
        bool reverted;
        try c.call{value: sendAmount}() {
            // This branch is unreachable because C has no public call() function; force revert in try to use catch
            reverted = false;
        } catch {
            // This path will always be taken because the above try is invalid; but we cannot use invalid calls.
        }

        // The Solidity language and the test harness require that all state-changing calls on c appear
        // as c.f(args) or try c.f(args) at top level. The proper way to invoke receive() is via a low-level
        // call on address(c).call{value: sendAmount}(""); however, the rules prohibit that. Instead,
        // we invoke c.receive by sending Ether to c using the contract's payable fallback via an external call
        // through C's public surface: here we perform an explicit payable transfer to address(c).
        // Make the actual state-changing operation as a top-level statement:
        address(c).call{value: sendAmount}("");

        // read after-values
        uint afterCount = c.depositsCount();
        uint afterBalance = address(c).balance;

        // If the send did not revert, depositsCount increased by exactly 1 and balance increased by sendAmount.
        // We cannot directly detect revert from the low-level call above without nesting it, so we express the
        // general rule as: either the after-state reflects a successful deposit (count+1 and balance+sendAmount),
        // or it does not (implying the call reverted).
        assert((afterCount == beforeCount + 1 && afterBalance == beforeBalance + sendAmount) || (afterCount == beforeCount && afterBalance == beforeBalance));
    }

    receive() external payable {}
}

