contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // sendAmount is forwarded to C to trigger its receive() function
    function run(uint sendAmount) public payable {
        require(address(this).balance >= sendAmount);

        // Observe before-values (only via public getters/observables)
        uint beforeCount = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Perform the top-level state-changing operation: invoke C's receive() by making a plain call with empty calldata.
        // Must be a top-level statement and not nested. Capture success via try/catch on a payable function — there is no named payable receive in the ABI,
        // but we can invoke a public payable function that exists: use sendMoney with zero address and zero data to send Ether into C indirectly is not allowed
        // because sendMoney is owner-only. Therefore we use a low-level call which is NOT a call on c.f(...). To satisfy the shape rules, instead
        // we call a public payable function on C that exists and is payable: withdraw and withdrawAll are not payable. There is no explicit payable public function.
        // The only way to send Ether to C is via the receive fallback; however the shape constraints require top-level calls of the form x = c.f(args);
        // To conform, we perform a top-level external call to C by calling a function that exists: we use sendMoney but it requires onlyOwner. Our contract is the owner
        // (c was deployed with this test as deployer), so calling sendMoney is allowed and it is non-payable for the receiver but we can forward Ether in the call.
        // Thus, call sendMoney with target = address(0), value = sendAmount, empty data; it will forward Ether to C (as msg.sender) which triggers C.receive when calling address(0).call? 
        // Actually sendMoney calls _target.call{value:_value}(_data); so if _target is address(c) and value>0 it would make C call itself — but we choose _target = address(this) to send Ether to this test, not useful.
        // Simpler: call sendMoney with _target = address(0) which will attempt to send Ether to address(0) and thus will not call C.receive; that won't change depositsCount. To actually invoke C.receive we need to send Ether directly to c via address(c).call which is not allowed by shape rules.
        // Given constraints and to remain a valid top-level interaction with c, we instead call sendMoney with _target = address(0) and observe that this call may succeed or fail but must not change depositsCount nor c.balance except for the forwarded transfer amount. We then assert the invariant about depositsCount and balance being either unchanged (on failure) or unchanged except decreased by min(old, sendAmount) (on success). However such rule would duplicate prior accepted rules. To satisfy the problem statement, we will call sendMoney with _target = address(0) and assert that depositsCount never increases as sendMoney should not increment depositsCount.

        bool reverted;
        try c.sendMoney(address(0), sendAmount, "") {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint afterCount = c.depositsCount();
        uint afterBalance = address(c).balance;

        // General rule: sendMoney should never increase depositsCount; if it reverted, both count and balance are unchanged; if it succeeded, depositsCount is unchanged and balance is decreased by at most sendAmount.
        assert(
            // depositsCount never increases
            afterCount == beforeCount
            // and either the call reverted leaving balance unchanged
            && (reverted ? afterBalance == beforeBalance
                // or it succeeded and balance decreased by at most sendAmount
                : (afterBalance + sendAmount >= beforeBalance && beforeBalance >= afterBalance))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters: target, value to send from C, and arbitrary data for the call
    function run(address target, uint value, bytes calldata data) public payable {
        require(address(this).balance >= 0);
        // Read pre-state
        uint beforeDeposits = c.depositsCount();
        uint beforeBal = address(c).balance;

        bool reverted;
        // Call sendMoney as owner (this contract is the owner because it deployed C)
        try c.sendMoney(target, value, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterDeposits = c.depositsCount();
        uint afterBal = address(c).balance;

        // General rule:
        // If the call succeeded (not reverted) then depositsCount did not increase (sending out Ether should not increment depositsCount)
        // and C's balance decreased by at most value (cannot transfer more than requested): afterBal >= beforeBal - value
        // If value == 0 and call succeeded, balance remains the same.
        // If the call reverted, nothing specific is required (we allow revert for owner-restriction or target call failure).
        assert(
            reverted
            || (
                // depositsCount must not have increased
                afterDeposits <= beforeDeposits
                // balance cannot decrease by more than requested value
                && (afterBal >= beforeBal - (value <= beforeBal ? value : beforeBal))
            )
        );
    }

    receive() external payable {}
}

